// The login pages' CSS variables, made from the same design values as the Ant Design theme (spec 007 UI-02,
// plan 007 section 5.1, PA4), so the login pages and the application cannot drift apart.
// Imports carry their .ts extension because Node runs this file directly (`npm run design:css`).
import { readableTextOn } from '../src/app/theme/contrast.ts';
import type { DesignValues } from '../src/app/theme/antdTheme.ts';

/** Where the generated file lives: Identity serves it to its own pages; committed, so Identity builds without Node. */
export const accountCssFile = new URL(
  '../../Services/Identity/Flowza.Identity.Api/wwwroot/account/assets/design-values.css',
  import.meta.url,
);

/** Values that are not CSS: the file's description, and breakpoints (CSS variables cannot be used in media queries). */
const skipped = new Set(['$description', 'breakpoints']);

/** Numbers are pixel sizes, except in these groups. */
const unitless = new Set(['font.weight']);

const header = `/* Generated by \`npm run design:css\` (src/Web/tooling/generate-account-css.ts) from
   src/Web/src/app/theme/designValues.json (spec 007 UI-02). Do not edit by hand: change the design values and
   run the command again; a test fails while this file and the design values differ. */`;

/** "textSecondary" → "text-secondary". */
function kebab(name: string): string {
  return name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

/** Depth-first walk of the design values: one variable per leaf, named by its path. O(number of values). */
function* variables(value: unknown, path: string[]): Generator<[string, string]> {
  if (typeof value === 'object' && value !== null) {
    for (const [key, child] of Object.entries(value)) {
      if (path.length === 0 && skipped.has(key)) {
        continue;
      }
      yield* variables(child, [...path, key]);
    }
    return;
  }
  const dotted = path.join('.');
  const isUnitless = [...unitless].some((group) => dotted.startsWith(`${group}.`));
  yield [
    `--flowza-${path.map(kebab).join('-')}`,
    typeof value === 'number' && !isUnitless ? `${value}px` : String(value),
  ];
}

/** The whole file: every design value as a `--flowza-*` variable; the brand is followed by the text colour readable on it (UI-07). */
export function renderAccountCss(values: DesignValues): string {
  const onBrand = readableTextOn(values.brand, values.onColour);
  const lines = [...variables(values, [])].flatMap(([name, value]) =>
    name === '--flowza-brand'
      ? [`  ${name}: ${value};`, `  --flowza-on-brand: ${onBrand};`]
      : [`  ${name}: ${value};`],
  );
  return `${header}\n:root {\n${lines.join('\n')}\n}\n`;
}
